using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using Microsoft.EntityFrameworkCore;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
namespace SysAdminAssistant.Desktop;
public partial class MainWindow
{
    private async Task EditInvoiceSettings()
    {
        var view=await remote.GetAsync<InvoiceSettingsView>("api/invoices/settings",lifetime.Token);var c=view.Settings;var m=c.Mailbox;
        var f=new FormDialog(this,"Распознавание счетов · почта",840).Toggle("enabled","Автоматически забирать счета",c.Enabled).Text("host","IMAP сервер",m.Host).Text("port","Порт TLS",m.Port.ToString()).Text("user","Логин",m.User).Secret("password","Пароль приложения · пусто = прежний").Text("folder","Папка",m.Folder).Text("interval","Период проверки · секунды",c.PollSeconds.ToString()).Toggle("new","Только новые письма после первой проверки",c.OnlyNew).Text("from","Или начиная с даты · ДД.ММ.ГГГГ",c.StartFromUtc?.ToServerTime().ToString("dd.MM.yyyy")??"").Text("senders","Отправители для автоматического добавления · по одному на строку",string.Join("\n",c.AllowedSenders),true).Toggle("auth","Проверять SPF / DKIM для автоматического добавления",m.RequireSpfDkim).Select("receiver","Принимающий сервер",new[]{new Choice(MailAuthReceiver.YandexMxFront,"Яндекс"),new Choice(MailAuthReceiver.Custom,"Другой · точные auth-id ниже")},m.AuthReceiver).Select("policy","Проверка доменов",new[]{new Choice(MailAuthPolicy.BothAligned,"SPF и DKIM совпадают с From"),new Choice(MailAuthPolicy.BothPassOneIdentity,"SPF и DKIM успешны, один совпадает с From")},m.AuthPolicy).Text("ids","Auth-id принимающей системы · по одному на строку",string.Join("\n",MailAuthentication.TrustedIds(m)),true).Toggle("sanitized","Принимающая система удаляет поддельные Authentication-Results со своими ID",m.AuthHeadersSanitized).Note("Рекомендуется отдельная папка/ящик для счетов. Настройки бэкапов и DMARC не меняются. При смене ящика, папки или начальной даты отметка загрузки создаётся заново. Список отправителей без проверки подлинности не разрешает автоматическое создание.").Note("OCR: "+(view.OcrReady?"модели включены":"модели не найдены; сканы останутся на проверке")+"\n"+view.Status);
        f.Note("Вложения автоматически распознаются только для отправителей из списка, прошедших проверку SPF/DKIM. Для остальных можно вручную загрузить проверенный файл.");
        InvoiceSettings Read(){c.Enabled=f.Checked("enabled");m.Host=f.Value("host").Trim();m.Port=int.Parse(f.Value("port"));m.User=f.Value("user");m.Folder=f.Value("folder");c.PollSeconds=int.Parse(f.Value("interval"));c.OnlyNew=f.Checked("new");c.StartFromUtc=f.Value("from").Length==0?null:AppTime.ToUtc(f.Date("from"));c.AllowedSenders=f.Value("senders").Split(['\n',';'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);m.RequireSpfDkim=f.Checked("auth");m.AuthReceiver=f.Selected<MailAuthReceiver>("receiver");m.AuthPolicy=f.Selected<MailAuthPolicy>("policy");m.TrustedAuthservId="";m.TrustedAuthservIds=f.Value("ids").Split(['\n',';'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).ToList();m.AuthHeadersSanitized=f.Checked("sanitized");return c;}
        f.ActionAsync("Проверить подключение",async()=>{await remote.PostAsync<InvoiceSettingsSave,bool>("api/invoices/test",new(Read(),f.Value("password"),view.Hash),lifetime.Token);AppMessageBox.Show(f,"TLS, вход и чтение выбранной папки работают.","Проверка счетов");});f.Validate=()=>{InvoiceSettingsStore.Validate(Read());return null;};if(f.ShowDialog()!=true)return;await remote.PostAsync<InvoiceSettingsSave,bool>("api/invoices/settings",new(Read(),f.Value("password"),view.Hash),lifetime.Token);
    }
    private async Task ReprocessInvoices(){var count=await remote.PostAsync<object,int>("api/invoices/reprocess",new{},lifetime.Token);AppMessageBox.Show(this,"Перепроверено ожидающих документов: "+count+". Платежи, уже созданные раньше, не менялись.","Счета");}
    private async Task ShowInvoiceHistory()
    {
        var rows=await remote.GetAsync<InvoiceHistory[]>("api/invoices/history",lifetime.Token);var window=new DialogWindow{Owner=this,Title="Счета · история обработки",Width=950,Height=600,WindowStartupLocation=WindowStartupLocation.CenterOwner};window.Content=Table(rows.Reverse(),("Время","Utc","dd.MM.yyyy HH:mm:ss"),("Результат","Message",null));window.ShowDialog();
    }
    private async Task ShowInvoiceTemplates()
    {
        var view=await remote.GetAsync<InvoiceSettingsView>("api/invoices/settings",lifetime.Token);var table=Table(view.Settings.Templates,("Поставщик / шаблон","Name",null),("Отправитель","Sender",null),("Автоматически","AutoCreate",null));var window=new DialogWindow{Owner=this,Title="Счета · поставщики и обучение",Width=960,Height=600,WindowStartupLocation=WindowStartupLocation.CenterOwner};var add=UiButton("Добавить");var edit=UiButton("Изменить / проверить");var delete=UiButton("Удалить");
        var gate=new AsyncActionGate();var canWrite=AccessRules.Level(remote.CurrentUser,"payments")>=2;
        void Selection(){add.IsEnabled=canWrite;edit.IsEnabled=table.SelectedItem is InvoiceTemplate;delete.IsEnabled=canWrite&&table.SelectedItem is InvoiceTemplate;}
        table.SelectionChanged+=(_,_)=>Selection();Selection();
        async Task RunTemplate(Func<Task> action){try{await gate.TryRunAsync(async()=>{add.IsEnabled=edit.IsEnabled=delete.IsEnabled=false;try{await action();}finally{Selection();}});}catch(OperationCanceledException)when(lifetime.IsCancellationRequested){}catch(Exception e){AppMessageBox.Show(window,e.Message,"Обучение счетов");}}
        async Task Save(){await remote.PostAsync<InvoiceSettingsSave,bool>("api/invoices/settings",new(view.Settings,"",view.Hash),lifetime.Token);view=await remote.GetAsync<InvoiceSettingsView>("api/invoices/settings",lifetime.Token);table.ItemsSource=view.Settings.Templates;Selection();}
        add.Click+=async(_,_)=>await RunTemplate(async()=>{var t=await EditInvoiceTemplate(window,new());if(t!=null){view.Settings.Templates.Add(t);await Save();}});edit.Click+=async(_,_)=>{if(table.SelectedItem is InvoiceTemplate t)await RunTemplate(async()=>{var next=await EditInvoiceTemplate(window,t);if(next!=null){view.Settings.Templates.RemoveAll(x=>x.Id==t.Id);view.Settings.Templates.Add(next);await Save();}});};delete.Click+=async(_,_)=>{if(table.SelectedItem is InvoiceTemplate t&&Confirm(window,"Удалить шаблон «"+t.Name+"»? Документы и платежи сохранятся."))await RunTemplate(async()=>{view.Settings.Templates.Remove(t);await Save();});};window.Content=ListSurface(table,[add,edit,delete],search:true);window.ShowDialog();
    }
    private async Task<InvoiceTemplate?> EditInvoiceTemplate(Window owner,InvoiceTemplate source)
    {
        var t=JsonSerializer.Deserialize<InvoiceTemplate>(JsonSerializer.Serialize(source))!;var docs=await LoadInvoices();await using var db=factory.Create();var recurring=await db.Payments.AsNoTracking().Where(p=>p.Repeat!=RepeatPeriod.None).ToArrayAsync();
        var f=new FormDialog(owner,"Обучение · правила поставщика",900).Text("name","Название шаблона",t.Name).Text("sender","Точный email отправителя",t.Sender).Text("subject","Фраза в теме · если у отправителя несколько форматов",t.SubjectContains).Text("supplier","Подтверждённый поставщик",t.Supplier).Text("inn","Подтверждённый ИНН",t.TaxId).Text("account","Подтверждённый расчётный счёт",t.BankAccount).Text("bik","Подтверждённый код банка / БИК",t.BankCode).Text("currency","Ожидаемая валюта",t.Currency).Text("days","Если срока в документе нет: дней от даты выставления · пусто = проверка",t.DueDays?.ToString()??"").Toggle("working","Считать рабочие дни по календарю компании",t.WorkingDays).Toggle("auto","Автоматически создавать разовый платёж после проверок",t.AutoCreate).Select("recurring","Связанный регулярный платёж · всегда проверить период",new[]{new Choice(null,"Нет")}.Concat(recurring.Select(p=>new Choice(p.Id,p.Title))),t.RecurringPaymentId);
        var fields=new[]{("Supplier","Поставщик"),("TaxId","ИНН"),("Kpp","КПП"),("Number","Номер счёта"),("InvoiceDate","Дата выставления"),("DueDate","Срок оплаты"),("Amount","Итоговая сумма"),("Currency","Валюта"),("BankAccount","Расчётный счёт"),("BankCode","БИК"),("Correspondent","Корреспондентский счёт")};
        f.Note("Обучение без внешнего ИИ: укажите подпись перед полем. Например, для суммы — «Всего к оплате». Значение берётся справа или со следующей строки. Для границы справа: «Всего: => НДС». Несколько разных совпадений требуют проверки. Ожидаемые реквизиты не подменяют отсутствующие или изменившиеся данные.");foreach(var (key,label) in fields)f.Text("anchor"+key,label+" · подпись перед значением",t.Anchors.GetValueOrDefault(key,""));
        f.Select("sample","Проверить на сохранённом счёте",new[]{new Choice(null,"Выбрать документ")}.Concat(docs.Select(d=>new Choice(d.Id,d.Id+" · "+d.Data.Supplier+" · "+d.Data.Number))),null);
        InvoiceTemplate Read(){t.Name=f.Value("name");t.Sender=f.Value("sender").Trim();t.SubjectContains=f.Value("subject");t.Supplier=f.Value("supplier");t.TaxId=f.Value("inn");t.BankAccount=f.Value("account");t.BankCode=f.Value("bik");t.Currency=f.Value("currency").Trim().ToUpperInvariant();t.DueDays=f.Value("days").Length==0?null:int.Parse(f.Value("days"));t.WorkingDays=f.Checked("working");t.AutoCreate=f.Checked("auto");t.RecurringPaymentId=f.Selected("recurring") as int?;t.Anchors=fields.Where(x=>f.Value("anchor"+x.Item1).Length>0).ToDictionary(x=>x.Item1,x=>f.Value("anchor"+x.Item1));return t;}
        f.ActionAsync("Посмотреть текст документа",async()=>{var id=f.Selected("sample") as int? ??throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("Выберите пример"));var doc=await remote.GetAsync<InvoiceView>("api/invoices/"+id,lifetime.Token);new FormDialog(f,"Текст счёта",900).Text("text","Распознанный текст",doc.Data.RawText,true,true).ViewOnly().ShowDialog();});
        f.ActionAsync("Проверить правила на примере",async()=>{var id=f.Selected("sample") as int? ??throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("Выберите пример"));var result=await remote.PostAsync<object,InvoiceData>("api/invoices/template-test",new{DocumentId=id,Template=Read()},lifetime.Token);new FormDialog(f,"Результат без сохранения платежа",900).Text("result","Найденные поля",JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}),true,true).ViewOnly().ShowDialog();});
        f.Validate=()=>Required(f.Value("name"),f.Value("sender"));return f.ShowDialog()==true?Read():null;
    }
}
